import type { MultiPolygon, Polygon } from 'geojson';
import type { BBox } from './pass';

export type RegionKind = 'country' | 'region' | 'state';

/** Properties stored in data/regions.geojson (generated by scripts/fetch-boundaries.ts). */
export interface RegionProperties {
  /** Stable id used in URLs: "br", "sul", "centro-oeste", "rs", ... */
  id: string;
  kind: RegionKind;
  /** IBGE abbreviation: "BR", "S", "RS", ... */
  code: string;
  name: string;
  ibgeCode?: number;
  parentId?: string;
}

export interface Region extends RegionProperties {
  bbox: BBox;
  geometry: Polygon | MultiPolygon;
}

/** Region without geometry, for list responses. */
export type RegionSummary = Omit<Region, 'geometry'>;
